"""Literal original metric children; Metrics parent styling is outside measured child boxes."""
from pathlib import Path
import re
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';j=(r/'docs/replica/source/original.js').read_text()
t=next(x for x in j.splitlines() if x.startswith('const t='))
template=re.search(r'<div class="metrics">(.*?)</div>\$\{resultChart\(\)\}',j).group(1)
script="let lang='ko';"+t+'''
const cases=[];for(const english of [false,true])for(const parentWidth of [326,656,904])for(const variant of [0,1,2]){
 lang=english?'en':'ko';const s={different:[0,45,999999][variant],unknown:[0,45,999999][variant],equal:[0,45,999999][variant]},state={run:{id:['UI-00000000','UI-MUZ1LP3S','UI-1234567890'][variant]}};
 const parent=document.createElement('div');parent.className='fixture metrics';parent.style.width=parentWidth+'px';parent.innerHTML=`'''+template+'''`;document.querySelector('#fixtures').append(parent);
 [...parent.children].forEach((item,index)=>{const kind=['different','unknown','equal','id'][index],id=`${english?'en':'ko'}-${parentWidth}-${kind}-${variant}`;item.dataset.id=id;cases.push({id,english,parentWidth,kind,label:item.children[0].textContent,value:item.children[1].textContent});});
}
function getCases(){return cases.map(c=>({...c,width:document.querySelector('[data-id="'+c.id+'"]').getBoundingClientRect().width}))}
function read(){return [...document.querySelectorAll('.fixture>div')].map(n=>{const r=n.getBoundingClientRect(),box=x=>{const b=x.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}},css=x=>Object.fromEntries(['fontFamily','fontSize','fontWeight','lineHeight','letterSpacing','color','marginTop','fontVariantNumeric'].map(k=>[k,getComputedStyle(x)[k]]));return{id:n.dataset.id,root:box(n),label:box(n.children[0]),value:box(n.children[1]),labelText:n.children[0].textContent,valueText:n.children[1].textContent,labelCSS:css(n.children[0]),valueCSS:css(n.children[1])}})}
'''
(o/'metricitem-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
(o/'metricitem-inner.html').write_text('<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="metricitem-original.css"><style>.fixture{position:absolute;left:30px;top:30px}.fixture:not(:first-child){visibility:hidden}</style><div id="fixtures"></div><script>'+script+'</script>')
(o/'metricitem.html').write_text('''<!doctype html><meta charset="utf-8"><title>MetricItem · original isolation</title><button id="metricitem-record">Record MetricItem</button><iframe width="1000" height="600" src="metricitem-inner.html"></iframe><script>document.querySelector('#metricitem-record').onclick=async()=>{const frame=document.querySelector('iframe');await frame.contentDocument.fonts.ready;const data={dpr:devicePixelRatio,cases:frame.contentWindow.getCases(),rows:frame.contentWindow.read()};const response=await fetch('/evidence/connection-metricitem-'+(new URLSearchParams(location.search).get('os')||'mac')+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!response.ok)throw Error('Record failed');document.querySelector('#metricitem-record').textContent='MetricItem recorded';}</script>''')
print('72 original metric children prepared')
animate=re.search(r"x\.animate\((\[\{transform:'translateY\(5px\)'.*?\}\],\{duration:220.*?\})\)",j).group(1)
(o/'metricitem-lifecycle.html').write_text('''<!doctype html><meta charset="utf-8"><title>MetricItem lifecycle · original isolation</title><link rel="stylesheet" href="metricitem-original.css"><button id="metricitem-run">Run MetricItem lifecycle</button><iframe src="metricitem-inner.html" hidden></iframe><div id="owned" class="metrics" style="width:500px;margin:30px"></div><script>document.querySelector('#metricitem-run').onclick=async()=>{const f=document.querySelector('iframe');await f.contentDocument.fonts.ready;const article=f.contentDocument.querySelector('[data-id="ko-904-different-1"]').cloneNode(true),holder=document.querySelector('#owned'),labelNode=article.children[0],valueNode=article.children[1],rows=[];function state(label){const s=getComputedStyle(valueNode);rows.push({label,attached:article.isConnected,opacity:article.isConnected?Number(s.opacity):null,y:article.isConnected?new DOMMatrix(s.transform).m42:null,sameLabel:labelNode===article.children[0],sameValue:valueNode===article.children[1],focusable:article.tabIndex>=0})}holder.append(article);state('attached-no-auto');const effect=valueNode.animate('''+animate+''');effect.pause();effect.currentTime=0;state('normal-start');effect.play();await effect.finished;state('normal-end');article.remove();state('detached');holder.append(article);state('reattached-no-auto');state('reduced');const id=f.contentDocument.querySelector('[data-id="en-656-id-2"]');labelNode.textContent=id.children[0].textContent;valueNode.className='mono';valueNode.textContent=id.children[1].textContent;article.style.width='100px';state('id-no-animation');const response=await fetch('/evidence/connection-metricitem-'+(new URLSearchParams(location.search).get('os')||'mac')+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows})});if(!response.ok)throw Error('Record failed');document.querySelector('#metricitem-run').textContent='MetricItem lifecycle recorded';}</script>''')
